import { CMA_TOPICS } from "@/data/cma-topics";
import type { CmaStudyUnitCase, CmaTopicGuide } from "@/data/cma-guides";

type Lesson = readonly [arTitle: string, enTitle: string, arBody: string, enBody: string];
type Case = readonly [arTitle: string, enTitle: string, arScenario: string, enScenario: string, arSolution: string, enSolution: string];
type Draft = readonly [id: string, arConcepts: string, enConcepts: string, lessons: readonly Lesson[], arWorkflow: string, enWorkflow: string, arPitfalls: string, enPitfalls: string, example: Case];

/** Independently written teaching adaptations of the supplied 2024 SU15–20 outlines. */
const drafts: Draft[] = [
  ["su15-variance-overview",
    "يقارن تحليل الانحرافات الفعلي بمعيار محدد مسبقًا، ثم يبحث السبب والمسؤول والفعل التصحيحي. الفرق المواتي يزيد الربح قياسًا بالمعيار، لكنه قد ينتج عن جودة أضعف أو طلب أقل. الإدارة بالاستثناء تركز على فروق كبيرة أو متكررة أو قابلة للسيطرة؛ وتُقرأ المؤشرات المالية مع الجودة والتسليم.",
    "Variance analysis compares actual results with predetermined standards, then investigates cause, ownership and corrective action. Favorable means a higher profit relative to the benchmark, but may arise from poorer quality or lower demand. Management by exception prioritizes material, recurring or controllable differences alongside quality and delivery measures.",
    [["فكك الفرق قبل الحكم", "Decompose before judging", "ميّز بين سعر المدخل وكمية استخدامه، وبين أثر حجم المبيعات وكفاءة التنفيذ. انحراف تكلفة قدره 8,000 مواتٍ مع انخفاض الإنتاج 20% قد يكون مجرد أثر الحجم. أعد صياغة الموازنة للحجم الفعلي، ثم حقق في كل جزء. ضع حدودًا للأهمية النسبية ولا تعتمد على رقم صافي يخفي فرقين متعاكسين.", "Separate input price from usage and sales volume from execution. A favorable 8,000 cost gap during a 20% production decline may simply reflect lower volume. Flex the budget to actual output, then investigate components. Set materiality thresholds; a small net number can conceal large offsets."],
     ["اربط الأسباب بالرقابة", "Assign causes with evidence", "تاريخ الشراء وسعر العقد يفسران فرق السعر؛ تقارير الخردة والجودة وساعات التعطل تفسر الكفاءة. قد يشتري قسم المشتريات مادة رخيصة فتزيد خسائر الإنتاج؛ لا تحاسب الإنتاج وحده على أثر قرار الشراء. وثق السبب والإجراء وصاحب القرار، ثم اختبر ما إذا كان المعيار قديمًا أو تغير السوق.", "Purchase dates and contracts inform price differences; scrap, quality and downtime logs explain efficiency. Cheaper material can cause production waste, so assigning all usage differences to production is unsound. Record the cause, action and decision owner, then ask whether the standard or market assumptions have changed."]],
    "حدد المعيار والفترة والحجم؛ احسب الفرق واتجاهه على الربح؛ فككه إلى سعر وكمية وحجم؛ تحقق من السبب والقدرة على التحكم؛ صحح العملية أو المعيار وتابع النتيجة.",
    "Define standard, period and activity; calculate the profit effect; decompose price, quantity and volume; investigate controllability; correct the process or standard and monitor outcomes.",
    "المواتي ليس مرادفًا للجيد؛ قد يخفي وفر شراء أولي هدرًا لاحقًا. لا تجمع انحرافات بإشارات واتفاقيات مختلفة دون تسوية اتجاه الربح.",
    "Favorable need not mean desirable; purchase savings may cause later waste. Align sign conventions before adding component variances.",
    ["فرق يحتاج تحقيقًا", "Investigate a variance", "خُطط لاستخدام 2 كغ لكل وحدة من 1,000 وحدة. أُنتج 800 وحدة واستُخدم 1,760 كغ بسعر معياري 5. هل انخفاض إجمالي المادة قياسًا بخطة 2,000 كغ دليل كفاءة؟", "The plan allowed 2 kg for each of 1,000 units. Actual production is 800 units consuming 1,760 kg at a standard price of 5. Does lower total consumption than the planned 2,000 kg prove efficiency?", "المسموح للإنتاج الفعلي 1,600 كغ؛ استُخدم 160 كغ فوقه، أي 800 غير مواتٍ. انخفاض الكمية عن الخطة الثابتة 240 كغ سببه الحجم ويخفي سوء الاستخدام.", "At actual output, 1,600 kg is allowed; excess 160 kg at 5 gives an 800 unfavorable usage variance. Consuming 240 kg less than the static plan reflects lower volume and hides inefficiency."]],
  ["su15-flexible-variance",
    "الموازنة الثابتة تثبت حجمًا واحدًا، والمرنة تعيد حساب الإيراد والتكلفة المتغيرة على النشاط الفعلي مع إبقاء الثابتة ضمن المدى الملائم. ينتقل الجسر من الثابتة إلى المرنة ثم إلى الفعلي؛ فرق الحجم = المرنة − الثابتة، وفرق الأداء = الفعلي − المرنة مع تفسير الإشارة بحسب الإيراد أو التكلفة.",
    "A static budget fixes one planned volume. A flexible budget recalculates revenue and variable cost at actual activity while keeping fixed costs constant within the relevant range. Reconcile static to flexible for volume, then flexible to actual for performance; a positive cost gap is unfavorable whereas a positive revenue gap is favorable.",
    [["ابنِ الجسر العددي", "Build the three-column bridge", "مبيعات الخطة 1,000 وحدة، هامش مساهمة معياري 20 للوحدة، وتكاليف ثابتة 8,000؛ الدخل المخطط 12,000. عند بيع 900 وحدة تصبح الموازنة المرنة 900×20−8,000=10,000. إذا بلغ الربح الفعلي 9,200 ففرق الحجم 2,000 غير مواتٍ وفرق الأداء 800 غير مواتٍ؛ المجموع 2,800 يطابق الفعلي ناقص الثابتة.", "At 1,000 planned units, standard contribution is 20 each and fixed cost 8,000; budgeted income is 12,000. For 900 actual units, flexible income is 900×20−8,000=10,000. If actual income is 9,200, the volume effect is 2,000 unfavorable and performance effect 800 unfavorable; together they explain the 2,800 static gap."],
     ["فرّق تكلفة الوحدة عن الثابت الكلي", "Flex variable cost only", "إذا كان متغير الإنتاج 6 للوحدة وثابت التشغيل 5,000، فتكلفة 800 وحدة المرنة 9,800. لا تضرب الثابت في نسبة 800 إلى الخطة؛ إن تجاوز الحجم مدى الطاقة الفعلية وكانت هناك خطوة تكلفة ثابتة جديدة، أعد نموذج التكلفة أولًا. افصل اختلاف حجم النشاط عن تغير سعر المورد أو كثافة المدخل.", "With variable cost 6 per unit and fixed operating cost 5,000, flexible cost for 800 units is 9,800. Do not scale total fixed cost with volume; if capacity steps up outside the relevant range, revise the model first. Then distinguish activity changes from supplier prices or input intensity."]],
    "استخرج معدلات الإيراد والتكاليف المتغيرة والثابتة من الخطة؛ مرّن على النشاط الفعلي؛ قارن المرنة بالثابتة ثم بالفعلي؛ طابق مجموع الفرقين مع الفرق الكلي.",
    "Extract standard unit rates and fixed amounts; flex to actual activity; compare flexible with static and actual; reconcile the components to the total gap.",
    "انخفاض تكلفة المواد الإجمالية مع مبيعات أقل ليس كفاءة تلقائيًا، وفرق الحجم له إشارة تختلف بين الإيراد والتكلفة؛ فسّر الأثر على الربح.",
    "Lower total material cost at lower volume is not automatically efficient; report the effect on profit, not a cost-only sign in isolation.",
    ["جسر ربح تشغيلي", "Operating-income bridge", "خططت شركة 2,000 وحدة بهامش 15 للوحدة وثابت 10,000. باعت 2,200 وحدة وحققت ربحًا فعليًا 21,000. احسب المخطط والمرن وفرقي الحجم والأداء.", "Plan: 2,000 units at 15 contribution each and fixed cost 10,000. Actual sales: 2,200 units with operating income 21,000. Find static and flexible income and the volume and performance effects.", "الثابتة 20,000؛ المرنة 23,000؛ فرق الحجم +3,000 مواتٍ، وفرق الأداء 21,000−23,000=2,000 غير مواتٍ، والفرق الكلي +1,000 مواتٍ.", "Static income 20,000; flexible income 23,000. Volume adds 3,000 favorable, performance subtracts 2,000 unfavorable, and actual exceeds static by 1,000 favorable."]],
  ["su15-materials-variance",
    "انحراف سعر المواد = كمية الشراء أو الاستخدام المحددة في السؤال ×(السعر الفعلي − المعياري). انحراف كمية المواد = السعر المعياري ×(الكمية المستخدمة فعليًا − الكمية المسموحة للإنتاج الفعلي). الجمع يفسر الفرق بين تكلفة المواد الفعلية والتكلفة المعيارية المطبقة إذا استُخدمت الكمية نفسها في جسر السعر.",
    "Material price variance is the relevant purchased or used quantity times actual less standard price, as specified. Usage variance is standard price times actual used less standard allowed for actual output. With a consistent quantity base, their sum reconciles actual input cost to standard cost allowed.",
    [["متى تسجل فرق السعر؟", "Purchase versus use recognition", "إذا اشتريت 1,100 كغ بسعر 7 بدل 8، ففرق سعر الشراء 1,100 مواتٍ ولو استُخدم 900 كغ فقط. عند تحليل تكلفة الإنتاج الحالي على أساس المستخدم، يكون فرق سعر الاستخدام 900 مواتٍ ويظل 200 متعلقًا بالمخزون. اذكر المقام وتوقيت القيد قبل الجمع مع فرق الكمية.", "Buying 1,100 kg at 7 instead of 8 yields a 1,100 favorable purchase-price variance even if only 900 kg was used. A current production-cost bridge based on usage uses 900 favorable; the remaining 200 relates to inventory. State the quantity base and timing before adding usage variance."],
     ["احسب المسموح من الناتج الفعلي", "Use actual-output allowance", "معيار 3 كغ للوحدة وإنتاج 400 وحدة يعني كمية مسموحة 1,200 كغ، وليس كمية خطة المبيعات. إذا استُخدم 1,260 بسعر معياري 8 ففرق الكمية 60×8=480 غير مواتٍ. اربط السبب بالخردة، ومهارة العمال، ومواصفة المادة ومصدرها؛ شراء الأرخص قد يزيد كمية الاستخدام.", "A 3 kg standard and 400 actual finished units allow 1,200 kg, regardless of planned sales. Using 1,260 kg at a standard 8 produces 480 unfavorable. Investigate scrap, labor skill, input specifications and suppliers; a lower purchase price can increase usage."]],
    "حدد سعرًا معياريًا وكمية مسموحة للإنتاج الفعلي؛ افصل فرق السعر على أساس الشراء أو الاستخدام المعلن؛ احسب فرق الكمية؛ طابق التكلفة وتحقق من جودة المادة.",
    "Determine standard price and actual-output allowance; compute price using stated purchased or used quantity; compute usage; reconcile cost and investigate quality.",
    "لا تستخدم كمية مشتراة في فرق السعر ثم تزعم أن المجموع يساوي تكلفة المستخدم دون تسوية تغير المخزون.",
    "A purchase-based price variance and a use-based production bridge need an inventory reconciliation.",
    ["سعر واستهلاك", "Price and usage", "إنتاج 500 وحدة بمعيار 2 كغ وسعر 6؛ استُخدم 1,080 كغ بسعر 5.50. احسب فرق السعر على المستخدم وفرق الكمية.", "Output is 500 units with 2 kg per unit at standard 6. Actual use is 1,080 kg at 5.50. Compute price variance on usage and usage variance.", "السعر =1,080×(5.50−6)=540 مواتٍ؛ المسموح 1,000 كغ، والكمية =6×80=480 غير مواتٍ؛ الصافي 60 مواتٍ، حيث تكلفة فعلية 5,940 مقابل مسموح 6,000.", "Price =1,080×(5.50−6)=540 favorable. Allowed use =1,000 kg; usage =80×6=480 unfavorable. Net 60 favorable reconciles actual 5,940 to standard 6,000."]],
  ["su15-labor-variance",
    "فرق معدل الأجر = الساعات الفعلية ×(الأجر الفعلي − المعياري)، وفرق الكفاءة = المعدل المعياري ×(الساعات الفعلية − ساعات المعيار للإنتاج الفعلي). لا تستخدم ساعات الموازنة الثابتة بدل المسموحة؛ يشمل المعدل الإضافي علاوة عمل إضافي أو اختلاف مهارة، بينما تعكس الساعات أوقات توقف وإعادة عمل.",
    "Labor rate variance is actual hours times actual less standard wage rate. Efficiency variance is the standard rate times actual hours less standard hours allowed for actual output. Overtime premium and labor mix may affect rate; downtime and rework affect hours.",
    [["حل جسر العمل", "Reconcile labor cost", "إذا أنتجت 600 وحدة بمعيار ساعتين وسعر 15، فالمسموح 1,200 ساعة وتكلفته 18,000. عند 1,250 ساعة بأجر 16 تكون التكلفة 20,000: فرق معدل 1,250 غير مواتٍ وفرق كفاءة 750 غير مواتٍ؛ مجموعهما 2,000. هذه التسوية تكشف إن كان السعر أو الاستهلاك هو المحرك الأكبر.", "At 600 units, 2 standard hours and a 15 rate, allowance is 1,200 hours costing 18,000. At 1,250 actual hours and 16 per hour, cost is 20,000: rate variance 1,250 unfavorable and efficiency variance 750 unfavorable. The 2,000 total reconciles actual and allowed cost."],
     ["فسّر التداخل التشغيلي", "Interpret operating interactions", "قد تتسبب عمالة مبتدئة أقل أجرًا في فرق معدل مواتٍ مع إعادة عمل تزيد ساعات التشغيل؛ كما قد يرفع تدريب متقن المعدل أولًا ويخفض العيوب والساعات لاحقًا. لا تُحمّل مدير الإنتاج كل فرق إذا كان جدول العمل الإضافي أو سياسة التوظيف بيد طرف آخر؛ استخدم تقارير الجودة والإنتاجية بجانب التكلفة.", "Less expensive junior staff can create a favorable rate and unfavorable efficiency through rework. Skilled training may raise the initial rate while lowering defects and hours later. Do not blame production for overtime or hiring decisions it cannot control; use quality and throughput reports as well."]],
    "احسب ساعات المعيار للمنتج الفعلي؛ استخرج المعدل الفعلي من الأجر والساعات إن لزم؛ احسب المعدل والكفاءة؛ طابق الفعلي بالمعيار وراجع أوقات التوقف.",
    "Derive allowed hours from actual units, obtain actual hourly rate, compute rate and efficiency, reconcile actual to standard cost, and investigate downtime.",
    "لا تقسّم الأجور الفعلية على ساعات معيارية لاستخراج معدل فعلي، ولا تستعمل الإنتاج المخطط لحساب الساعات المسموحة.",
    "Do not derive actual wage rate from standard hours, or use planned output for the hours allowed.",
    ["تأثير الأجر والكفاءة", "Wage and efficiency effects", "إنتاج 400 وحدة بمعيار 1.5 ساعة و20 لكل ساعة؛ الساعات الفعلية 630 والتكلفة الفعلية 13,230. احسب الفرقين.", "Output is 400 units at 1.5 standard hours and 20 per hour. Actual hours are 630 and labor cost is 13,230. Find both variances.", "الأجر الفعلي 13,230÷630=21؛ فرق المعدل 630×1=630 غير مواتٍ؛ المسموح 600 ساعة، فرق الكفاءة 30×20=600 غير مواتٍ؛ الإجمالي 1,230.", "Actual rate =13,230/630=21; rate variance 630 unfavorable; allowed hours 600, efficiency variance 30×20=600 unfavorable; total 1,230."]],
  ["su15-mix-yield",
    "عندما تقبل العملية بدائل للمدخلات، يفصل فرق الكفاءة إلى أثر تغير نسب الأصناف (المزيج) وأثر تغير مجموع المدخلات اللازمة للناتج (المردود). احسب متوسط السعر المعياري بمزيج معياري SMSP وبمزيج فعلي AMSP، ثم قارن على نفس مجموع المدخلات الفعلية؛ وتحدد إشارة النتيجة حسب أثرها على التكلفة.",
    "For substitutable inputs, decompose efficiency into composition (mix) and total input consumption (yield). Calculate the weighted standard input price under the standard mix (SMSP) and actual mix (AMSP), then compare at the same actual total quantity; interpret signs by cost impact.",
    [["ثبّت مجموع المدخل عند فحص المزيج", "Hold total input constant for mix", "معيار المادة A بنسبة 60% وسعر 10، وB بنسبة 40% وسعر 5؛ متوسط المعيار 8. عند استخدام 100 كغ بنسبة 50% لكل نوع، يكلف المزيج بسعر معياري 750 بدل 800 عند النسب الأصلية، فيكون 50 مواتٍ. لا تخلط هذا بوفر حجم المدخلات إذا تغير مجموع الكيلوغرامات.", "Standard A is 60% at 10 and B 40% at 5, so SMSP is 8. For 100 kg at an actual 50/50 mix, standard-price cost is 750 rather than 800 under the standard mix: mix is 50 favorable. This holds total input at 100 kg and does not yet measure total usage."],
     ["المردود يكمل التسوية", "Yield closes the bridge", "إذا كان مجموع المدخل المسموح للإنتاج الفعلي 90 كغ لكن المستخدم 100، ففرق المردود بتكلفة مزيج معياري 8 يساوي 80 غير مواتٍ. مع فرق المزيج 50 مواتٍ، يصبح فرق الكفاءة الكلي 30 غير مواتٍ؛ تحقق: تكلفة المدخل المستخدم بالأسعار المعيارية 750 مقابل مسموح 90×8=720.", "If 90 kg is allowed for actual output but 100 is used, yield at SMSP 8 is 80 unfavorable. Combined with a 50 favorable mix, total efficiency is 30 unfavorable: actual mix at standard prices costs 750 versus allowed 90×8=720. Exclude purchase-price effects from this reconciliation."]],
    "حدد نسب وأسعار المعيار؛ احسب SMSP وAMSP؛ احسب المزيج = ATQ×(AMSP−SMSP) والمردود = SMSP×(ATQ−STQ) بصيغة فرق تكلفة؛ اجمع وطابق.",
    "Find standard proportions and prices; compute SMSP and AMSP; cost-sign mix = ATQ×(AMSP−SMSP), yield = SMSP×(ATQ−STQ); sum and reconcile.",
    "قد تعرض المراجع المعادلتين بعكس الإشارة؛ التزم بتسمية المواتي وغير المواتي. لا تطبق فرق مزيج على مدخل غير قابل للاستبدال وظيفيًا.",
    "Sources may reverse algebraic signs; label favorable/unfavorable by cost effect. A mix variance requires genuinely substitutable inputs.",
    ["مزيج ومردود مادة", "Material mix and yield", "معيار A: 60% بسعر10 وB: 40% بسعر5؛ المسموح90 كغ. استُخدم100 كغ نصفها A ونصفها B. احسب فرق المزيج والمردود.", "Standard mix is 60% A at 10 and 40% B at 5; 90 kg is allowed. Actual use is 100 kg, half A and half B. Compute mix and yield variances.", "SMSP=8 وAMSP=7.5؛ المزيج100×(7.5−8)=50 مواتٍ؛ المردود8×(100−90)=80 غير مواتٍ؛ الصافي30 غير مواتٍ.", "SMSP=8, AMSP=7.5. Mix =100×(7.5−8)=50 favorable; yield =8×(100−90)=80 unfavorable; net 30 unfavorable."]],
  ["su15-overhead-variance",
    "يُحلل المتغير إلى إنفاق = AH×(معدل فعلي للساعة − معدل معياري)، وكفاءة = معدل معياري×(AH−SH). في الثابت، فرق الإنفاق = ثابت فعلي−ثابت مخطط، وفرق الحجم = ثابت مخطط−ثابت مطبق على ساعات معيارية للإنتاج الفعلي. لا يوجد فرق كفاءة مستقل للثابت في هذا التحليل.",
    "Variable overhead splits into spending = AH×(actual driver rate−standard rate) and efficiency = standard rate×(AH−SH). Fixed overhead splits into budget/spending = actual−budget and production-volume = budget−standard applied to actual output. There is no separate fixed-overhead efficiency variance in this framework.",
    [["أربع خانات دون خلط", "Four distinct buckets", "متغير صناعي فعلي 13,200 على 2,200 ساعة، ومعدل معياري 5، والمسموح 2,000 ساعة: معدل فعلي 6؛ الإنفاق 2,200 غير مواتٍ والكفاءة 1,000 غير مواتٍ؛ مجموعهما 3,200 مقابل المسموح 10,000. لا تستخدم عدد وحدات مبيعات بدل ساعات محرك التكلفة.", "Variable overhead actual 13,200 on 2,200 hours, with standard 5 and 2,000 allowed hours: actual rate 6. Spending is 2,200 unfavorable; efficiency 1,000 unfavorable, totaling 3,200 over allowed 10,000. Use the overhead driver hours, not sold-unit counts."],
     ["مقام تحميل الثابت وحجمه", "Fixed rate and volume", "ثابت مخطط 24,000 لطاقة معيارية 3,000 ساعة، فيكون المعدل8. إذا سمح الناتج بـ2,800 ساعة فالثابت المطبق 22,400، وفرق الحجم 1,600 غير مواتٍ. وإذا أنفق فعليًا 23,500 ففرق الإنفاق 500 مواتٍ؛ الصافي 1,100 غير مواتٍ. بقاء الثابت نفسه لا يلغي فرق الحجم.", "Budgeted fixed overhead 24,000 on a 3,000 standard-hour denominator yields 8/hour. At 2,800 allowed hours, applied fixed overhead is 22,400, a 1,600 unfavorable volume variance. Actual fixed spend 23,500 gives 500 favorable spending, net 1,100 unfavorable. Fixed spending can be unchanged while volume still differs."]],
    "حدد محرك المتغير ومعدل تطبيق الثابت؛ احسب الساعات الفعلية والمسموحة؛ حلل المتغير إلى إنفاق وكفاءة والثابت إلى إنفاق وحجم؛ طابق الفعلي بالمطبق.",
    "Identify driver and fixed-rate denominator; calculate actual and allowed hours; split variable spending/efficiency and fixed spending/volume; reconcile actual to applied.",
    "لا تضرب التكلفة الثابتة في نسبة النشاط عند المرونة، ولا تصف فرق حجم التحميل بأنه فرق إنفاق نقدي فعلي.",
    "Do not flex fixed spending proportionately to volume or describe underapplied fixed overhead as extra cash spent.",
    ["تسوية صناعية", "Overhead reconciliation", "متغير صناعي فعلي 13,200 لـ2,200 ساعة ومعدل معياري5 والمسموح2,000؛ الثابت الفعلي23,500 والمخطط24,000، معدل تحميله8 والمسموح2,800 ساعة. ما مجموع الفروق؟", "Variable overhead actual 13,200 for 2,200 hours; standard rate 5 and allowed 2,000. Fixed actual 23,500, budget 24,000, applied rate 8 and allowed 2,800 hours. Find total overhead variance.", "المتغير 3,200 غير مواتٍ؛ الثابت 23,500−22,400=1,100 غير مواتٍ (إنفاق 500 مواتٍ وحجم 1,600 غير مواتٍ). الإجمالي 4,300 غير مواتٍ، مقابل مسموح 10,000+22,400=32,400 وفعلي 36,700.", "Variable is 3,200 unfavorable; fixed actual less applied =1,100 unfavorable (500 favorable spending, 1,600 unfavorable volume). Total 4,300 unfavorable; actual 36,700 versus allowed/applied 32,400."]],
  ["su15-comprehensive",
    "الحالة المتكاملة تبدأ بالناتج الفعلي لتكوين الكميات والساعات المسموحة، ثم تضع السعر الفعلي والكمية الفعلية أمام السعر والكمية المعياريين لكل بند. تسوية المواد والعمل والمتغير والثابت تمنع حساب فرق مرتين؛ ويُعرض فرق الحجم المنفصل عند مقارنة نتائج الفعلي بالخطة الثابتة.",
    "An integrated variance case first derives allowed inputs from actual output, then sets actual rate and quantity against standards for each input. Material, labor, variable and fixed overhead bridges must reconcile without double-counting; a separate sales-volume bridge explains static versus flexible operating income.",
    [["جدول واحد بثلاث قيم لكل مدخل", "Three values per cost driver", "اكتب تكلفة فعلية = AQ×AP، ثم وسيطة = AQ×SP، ثم معيارية مسموحة = SQ×SP. الفرق بين الأولى والوسيطة للسعر، وبين الوسيطة والأخيرة للكمية. في العمل استبدل الكمية بالساعات، وفي المتغير الصناعي استخدم ساعات المحرك؛ أما الثابت فقارن الفعلي بالمخطط ثم المخطط بالمطبق.", "For each input write actual AQ×AP, bridge AQ×SP, and allowed SQ×SP. First gap is price, second usage. Labor uses hours; variable overhead uses driver hours. Fixed overhead instead compares actual with budget and budget with applied. This layout prevents multiplying the wrong rate by the wrong quantity."],
     ["أثبت التطابق النهائي", "Prove the reconciliation", "إذا الفعلي للمواد 6,480 والمسموح 6,000، والعمل 13,230 مقابل 12,000، والمتغير 7,350 مقابل 7,000، والثابت 18,500 مقابل مطبق 18,000، ففروق البنود غير المواتية 480+1,230+350+500=2,560. فرق 2,560 يجب أن يساوي إجمالي الفعلي 45,560 ناقص إجمالي المسموح 43,000، قبل النظر إلى فرق إيراد المبيعات.", "If actual versus allowed costs are materials 6,480/6,000, labor 13,230/12,000, variable overhead 7,350/7,000 and fixed overhead 18,500/18,000 applied, item gaps total 480+1,230+350+500=2,560 unfavorable. It equals total actual 45,560 less total allowed 43,000, before sales-revenue effects."],
     ["بعد الأرقام: خطة علاج", "From variance to action", "تحقق في تجاوز ساعات العمل ومواد الخردة معًا؛ فقد يكون التغيير في المورد سببًا مشتركًا. راجع السعر التعاقدي، إنتاج الوحدات الجيدة، توقفات الآلة والأحداث غير المتكررة. لا تكافئ الوفر المنفرد مع انخفاض الجودة أو حمّل كل التباين لمدير لا يملك القرار.", "Investigate labor hours and material scrap together; a supplier change could drive both. Review contracts, good units, machine downtime and one-off events. A favorable isolated price is not an achievement if quality falls, and accountability follows authority."]],
    "ثبّت الناتج الفعلي؛ احسب الكميات والساعات المسموحة؛ أنشئ جسور الأسعار والاستخدام والإنفاق والحجم؛ طابق إجمالي الفروق ثم حدد الأسباب المشتركة وخطة المعالجة.",
    "Fix actual output; derive allowances; build price, usage, spending and volume bridges; reconcile total differences; assign joint causes and actions.",
    "لا تجمع فرق سعر الشراء مع فرق استخدام الإنتاج دون تسوية تغير مخزون الخام؛ ولا تخلط فرق المبيعات مع فروق تكلفة التصنيع.",
    "Reconcile raw inventory before adding a purchase-price variance to a use-based bridge; keep sales and manufacturing effects separate.",
    ["تجميع الفروق", "Add the cost gaps", "فروق المواد 480، والعمل 1,230، والمتغير الصناعي 350، والثابت 500 كلها غير مواتية. الفعلي الإجمالي 45,560. ما المسموح ونوع الفرق الكلي؟", "Materials, labor, variable overhead and fixed overhead are respectively 480, 1,230, 350 and 500 unfavorable. Total actual cost is 45,560. Find allowed cost and total variance.", "الإجمالي 2,560 غير مواتٍ؛ التكلفة المسموحة 45,560−2,560=43,000. لا يعني جمع الفروق وحده معرفة السبب أو المسؤول.", "Total 2,560 unfavorable; allowed cost 45,560−2,560=43,000. The arithmetic reconciliation alone does not identify cause or responsibility."]],
  ["su15-sales-variance",
    "لمنتج واحد، فرق سعر البيع = الكمية الفعلية×(السعر الفعلي−المعياري)، وفرق حجم المبيعات = (الكمية الفعلية−المخططة)×هامش المساهمة المعياري. في المنتجات المتعددة يتفكك أثر الحجم إلى تغير العدد الكلي والمزيج؛ وقد ينقسم أثر العدد إلى حجم السوق وحصة المنشأة منه.",
    "For one product, sales price variance is actual quantity×(actual−standard price), and sales volume variance is (actual−budgeted units)×standard unit contribution. For several products, volume separates total quantity and mix; quantity can further split market size and market share.",
    [["سعر وحجم لهامش المساهمة", "Price and volume at contribution", "خططت المنشأة 1,000 وحدة بسعر 30 وتكلفة متغيرة 18، فالهامش 12. باعت 1,100 بسعر 29 مع بقاء التكلفة المتغيرة 18. فرق السعر =1,100×(29−30)=1,100 غير مواتٍ، وفرق الحجم =100×12=1,200 مواتٍ؛ الصافي 100 مواتٍ، ومساهمة الفعلي 12,100 مقابل خطة 12,000.", "Plan: 1,000 units at price 30 and variable cost 18, standard margin 12. Actual: 1,100 at 29 with variable cost still 18. Price is 1,100 unfavorable, volume is 1,200 favorable, net 100 favorable; contribution is 12,100 versus planned 12,000."],
     ["المزيج والسوق", "Mix, market size and share", "عند خط إنتاج ذي هامشين مختلفين، انقل العدد الفعلي أولًا إلى نسب المزيج المخطط ثم إلى نسب المزيج الفعلية؛ يفسر الفرق الأخير مزيج البيع. وإذا نما السوق 10% وحصة الشركة انخفضت من 20% إلى 18% فلا تُنسب زيادة السوق لإدارة المبيعات وحدها. استخدم هوامش معيارية ثابتة لعزل أثر الكمية عن تغير السعر.", "For multiple products, apply the planned mix to actual total volume, then compare it with actual mix; the second bridge measures mix. If the market grows 10% but company share slips from 20% to 18%, rising units cannot all be credited to sales. Hold standard contribution margins fixed to isolate quantity from selling price."],
     ["حدود الإشارة", "Sign conventions", "فرق إيراد موجب قد يكون مواتيًا لكن فرق تكلفة موجب غير مواتٍ. في المنتج الواحد لا يوجد فرق مزيج، وإن انخفض سعر الوحدة فقد يتحسن إجمالي المساهمة عندما يعوضه الحجم؛ القرار يتطلب فحص الربح والاستدامة وطاقة التسليم.", "A positive revenue gap is favorable but a positive cost gap is unfavorable. Single-product mix is zero, and a lower selling price can still raise total contribution if additional volume compensates. Check profit, durability and delivery capacity rather than price alone."]],
    "احسب الهامش المعياري؛ ثبت الكمية الفعلية في فرق السعر؛ طبق الهامش المعياري على تغير الحجم؛ افصل العدد والمزيج والسوق عند تعدد المنتجات ثم طابق المساهمة.",
    "Calculate standard unit margin; hold actual units for price variance; apply standard margin to volume changes; for multiple products split quantity, mix, market effects and reconcile contribution.",
    "لا تضرب فرق حجم المبيعات في سعر البيع الكامل إن كان المطلوب أثر الربح؛ استخدم هامش المساهمة.",
    "For profit effects, multiply volume by standard contribution margin, not full selling price.",
    ["تغير المساهمة", "Contribution bridge", "خططت المنشأة 1,000 وحدة بسعر30 ومتغير18؛ باعت1,100 بسعر29 مع ثبات تكلفة الوحدة. كم فرق السعر والحجم وصافي المساهمة؟", "Budget 1,000 units at price 30 and variable cost 18; sell 1,100 at price 29 with unchanged variable unit cost. Find price, volume and net contribution differences.", "السعر 1,100 غير مواتٍ؛ الحجم 100×12=1,200 مواتٍ؛ الصافي100 مواتٍ؛ الفعلي 1,100×11=12,100 مقابل 12,000 مخطط.", "Price 1,100 unfavorable; volume 100×12=1,200 favorable; net 100 favorable. Actual contribution 1,100×11=12,100 versus planned 12,000."]],
  ["su16-responsibility-centers",
    "تفوض المنشأة قرارات إلى مراكز تكلفة أو إيراد أو ربح أو استثمار. تُقاس الإدارة بما تستطيع التأثير فيه خلال الفترة: مدير التكلفة يضبط النفقة، ومدير الربح يتحكم في الإيراد والنفقة، ومدير الاستثمار يوجه الأصول أيضًا. لا تُحمّل تكاليف الإدارة المشتركة اعتباطيًا ضمن تقييم شخصي ولو ظهرت في ربحية المركز الكاملة.",
    "Decentralization assigns decisions to cost, revenue, profit and investment centers. Evaluate managers on factors they can influence in the period: costs, revenue, both, or income plus capital respectively. Common head-office allocations can be useful for total product economics but distort personal accountability if beyond the manager's authority.",
    [["من يملك القرار؟", "Authority defines the center", "قسم خدمة داخلي يتلقى ميزانية تنظيف لا يسعر خدماته عادةً: مركز تكلفة. فريق بيع يقرر الحملات والخصومات لكنه لا يدير الإنتاج: مركز إيراد مع مساءلة مصاريفه القابلة للتحكم. فرع يدير أسعارًا وتكاليف ومعدات: مركز استثمار. يتغير التصنيف عند تغير الصلاحية الفعلية، لا بسبب اسم الإدارة.", "A cleaning department without pricing discretion is a cost center. A sales team that sets campaigns and discounts but not factory capacity is generally a revenue center, with its own controllable expenses still monitored. A branch controlling price, cost and equipment is an investment center. Classify by decision rights, not the department's label."],
     ["التكاليف المشتركة وتوافق الأهداف", "Common cost and goal congruence", "إذا وزعت الإدارة 50,000 إيجار مكتب رئيسي على الفروع بنسبة المبيعات، ينخفض الربح المحاسبي لكل فرع لكن لا يستطيع مدير الفرع إلغاء الإيجار. أعرض مساهمة قابلة للتحكم للمدير وربحية بعد المصروفات المشتركة لاتخاذ قرار الشركة. ربط الحافز بمؤشر واحد قد يحسن نتيجة قسم على حساب العملاء أو بقية الأقسام.", "Allocating 50,000 head-office rent by branch sales lowers reported segment profit but local managers may have no power over that rent. Show controllable contribution for manager evaluation and full cost for corporate decisions. An incentive tied to one metric can improve a segment while harming customers or other units."]],
    "حدد صلاحيات السعر والإنفاق والأصول؛ صنف المركز؛ افصل القابل للتحكم عن المشترك؛ اختر مؤشرات متوازنة وحلل آثار القرارات على المنشأة كلها.",
    "Map authority over price, costs and assets; classify the center; separate controllable from common items; choose balanced metrics and inspect company-wide effects.",
    "التكلفة المخصصة ليست تلقائيًا تحت سيطرة مدير المركز؛ لا تساوِ بين خسارة محاسبية وقرار إغلاق دون تحليل التكلفة الممكن تجنبها.",
    "Allocated costs are not necessarily controllable; a reported loss alone does not justify closure without avoidable-cost analysis.",
    ["مركز الفرع", "Classify a branch", "فرع يقرر الأسعار والأجور وشراء آلاته في حدود معتمدة. ما نوعه؟ وما رقم لا ينبغي استخدامه وحده لتقييم المدير؟", "A branch sets prices and wages and selects its equipment within an approved limit. What kind of responsibility center is it, and which charge should not alone drive manager evaluation?", "هو مركز استثمار لأنه يؤثر في الربح ورأس المال. إيجار المكتب الرئيسي الموزع على أساس الإيرادات لا يثبت كفاءة مدير الفرع؛ اعرضه منفصلًا.", "It is an investment center because it influences income and assets. Allocated head-office rent does not establish the branch manager's performance and should be shown separately."]],
  ["su16-cost-revenue-profit",
    "يُقاس مركز التكلفة بانحراف تكلفة مرنة ومخرجات الجودة، ومركز الإيراد بوحدات المبيعات والسعر والتحصيل، ومركز الربح بمساهمة قابلة للتحكم وربح القطاع. هامش القطاع بعد تكاليفه الثابتة القابلة للتتبع يختلف عن صافي ربح بعد تكاليف مشتركة؛ تقرير متعدد الأعمدة يكشف أثر كل مستوى.",
    "Cost centers use flexible-cost and quality measures; revenue centers use price, units and collections; profit centers use controllable contribution and segment margin. Segment margin after traceable fixed cost differs from reported profit after common allocations. A layered contribution report makes that distinction visible.",
    [["تقرير ربح القطاع", "Segment contribution ladder", "مبيعات قسم 200,000، ومتغير 120,000؛ مساهمته 80,000. ثابت مباشر قابل للتتبع 30,000 يجعل هامش القطاع 50,000؛ وتخصيص مركزي 20,000 يعطي ربحًا معلنًا 30,000. قد يكون هامش 50,000 مناسبًا لتقييم استمرار القسم، فيما يستبعد تقرير أداء المدير جزءًا من الثابت المباشر إن لم يملك قراره.", "With revenue 200,000 and variable cost 120,000, contribution is 80,000. Traceable fixed cost 30,000 leaves segment margin 50,000; a common allocation of 20,000 leaves reported 30,000. Segment decisions consider the traceable level; manager evaluation may exclude even some direct fixed cost if outside local control."],
     ["مؤشرات مساندة لا تحل محل التفسير", "Pair finance with operations", "انخفاض تكاليف قسم خدمة قد يصاحبه تأخير وإعادة عمل، وارتفاع مبيعات قسم آخر قد يأتي بخصومات تضعف الهامش أو بديون عسيرة التحصيل. قارن تكلفة الوحدة الملائمة بالنشاط الفعلي، ومعدلات العيوب، والتسليم في الموعد، وجودة الإيراد لا مجرد إجمالي المصروف أو المبيعات.", "Lower support costs may increase delays and rework. Higher revenue from aggressive discounts or uncollectible credit can reduce profit. Compare costs at actual activity and monitor defects, timely delivery and collection quality, not just spending or revenue totals."]],
    "كوّن تقرير المبيعات ثم المتغير والثابت القابل للتتبع ثم المشترك؛ حدد بندًا تحت سيطرة المدير وآخر خارجها؛ أضف مؤشرات جودة وتحصيل وأعد مقارنة النشاط بالمرن.",
    "Layer revenue, variable, traceable and common costs; identify controllability; add quality and collection metrics; compare spending with activity-adjusted standards.",
    "لا تخصم تكلفة مشتركة غير قابلة للتجنب مرتين أو تصف هامش مساهمة موجبًا بأنه ربح نهائي.",
    "Do not double count unavoidable common charges or call positive contribution final profit.",
    ["هامش القطاع", "Find segment margin", "مبيعات 180,000 ومتغير 100,000 وثابت مباشر 25,000 ومشترك موزع 15,000. احسب المساهمة وهامش القطاع والربح بعد التخصيص.", "Revenue is 180,000, variable cost 100,000, traceable fixed cost 25,000 and allocated common cost 15,000. Find contribution, segment margin and profit after allocation.", "المساهمة 80,000؛ هامش القطاع 55,000؛ بعد المشترك 40,000. لا تنسب تخصيص 15,000 تلقائيًا إلى قرارات المدير.", "Contribution 80,000; segment margin 55,000; after common charge 40,000. The 15,000 allocation need not reflect the manager's decisions."]],
  ["su16-investment-centers",
    "العائد على الاستثمار ROI = ربح التشغيل ÷ رأس المال المستثمر، ويمكن فكه إلى هامش الربح × معدل دوران الأصول. الدخل المتبقي RI = الربح − (الأصول × معدل العائد المطلوب). قد يرفض مدير يقيّم على متوسط ROI مشروعًا بعائد أعلى من حد الشركة لكنه أقل من ROI الحالي؛ RI يعالج هذا التضارب جزئيًا ويحتاج معدل تكلفة رأسمال مناسبًا للمخاطر.",
    "ROI = operating income/invested assets, also profit margin×asset turnover. Residual income = operating income−invested assets×required return. A manager paid on average ROI may reject a project above the company's hurdle but below the center's current ROI; RI reduces this conflict when the capital charge reflects risk.",
    [["افصل الهامش والدوران", "Decompose ROI", "إذا الإيراد 1,000,000 والربح 100,000 والأصول 500,000، فالهامش 10% والدوران 2 والعائد 20%. يستطيع القسم رفع العائد بتحسين هامش التشغيل أو زيادة المبيعات لكل ريال أصول، لكن بيع أصل لازم للإنتاج قد يرفع النسبة مؤقتًا ويضر طاقة الخدمة. ثبت تعريف الأصول ومتوسط الرصيد بين المقارنات.", "With sales 1,000,000, operating profit 100,000 and assets 500,000, margin is 10%, turnover 2 and ROI 20%. Either margin or asset use can raise ROI, but selling essential equipment may flatter the ratio while harming service. Use a consistent asset denominator, often average assets, for comparisons."],
     ["قرار مشروع هامشي", "Incremental project test", "مركز عائده الحالي 20% يجد مشروعًا يتطلب 100,000 ويضيف 15,000 سنويًا؛ سيهبط متوسط ROI لكنه يولد 5,000 دخلًا متبقيًا إضافيًا عند معدل مطلوب 10%. لدى قرار الشركة قيمة إيجابية بحسب الفرضيات، ولا ترفضه لمجرد أن نسبته أقل من متوسط القسم.", "A 20% ROI center considers a 100,000 investment adding 15,000 annual income. Average ROI falls, yet at a 10% hurdle incremental RI rises 5,000. From the firm's perspective it adds value under these assumptions; compare marginal return with the hurdle, not the historic average."]],
    "وحّد تعريف الربح والأصول؛ احسب ROI والهامش والدوران؛ احسب تكلفة رأس المال وRI؛ قيّم المشروع على أثره الإضافي وحساسية الأصول والتوقيت.",
    "Define income and asset base consistently; compute ROI, margin and turnover; apply capital charge for RI; assess incremental project returns and asset timing.",
    "لا تقارن RI الدولاري بين مراكز متفاوتة الحجم بلا سياق، ولا تجعل هدف رفع ROI يثني عن مشروع تتجاوز عوائده تكلفة رأس المال.",
    "Dollar RI is size-dependent; a high average ROI can lead to rejecting a project above the firm's hurdle.",
    ["العائد والدخل المتبقي", "ROI and residual income", "فرع ربحه التشغيلي 90,000 وأصوله 600,000؛ معدل مطلوب 10%. احسب ROI وRI. مشروع جديد يكلف 100,000 ويضيف 12,000؛ كيف يتغير RI؟", "A branch earns 90,000 operating income on 600,000 invested assets; hurdle 10%. Find ROI and RI. A new 100,000 project adds 12,000 income. What is incremental RI?", "ROI=15%؛ RI=90,000−60,000=30,000؛ المشروع يضيف 12,000−10,000=2,000 إلى RI، وإن خفض متوسط العائد قليلًا.", "ROI=15%; RI=90,000−60,000=30,000. The project adds 12,000−10,000=2,000 RI even if the average ROI declines slightly."]],
  ["su16-balanced-scorecard",
    "بطاقة الأداء المتوازن تترجم الاستراتيجية إلى أربع زوايا: المال، والعميل، والعمليات الداخلية، والتعلم والنمو. تمثل مهارة الموظف ووقت الدورة والاحتفاظ بالعميل مؤشرات تقود نتائج مالية لاحقة؛ ينبغي تحديد أهداف ومسؤوليات ونطاق بيانات لكل مؤشر حتى لا تصبح البطاقة قائمة أرقام منفصلة.",
    "The balanced scorecard translates strategy into financial, customer, internal-process and learning/growth perspectives. Skills, cycle time and retention may lead later financial outcomes. Each metric needs a strategic objective, owner, credible data and a causal hypothesis, rather than a list of disconnected targets.",
    [["سلسلة سبب ونتيجة", "Link leading and lagging measures", "استثمار التدريب يرفع دقة الطلبات، فتقل إعادة العمل ووقت التسليم، وقد يرفع رضا العميل وتكرار الشراء وصولًا إلى الهامش. ضع مؤشرًا للتدريب والعيوب والتسليم والاحتفاظ مع فترة قياس؛ افحص العلاقة بدل افتراضها. الربح مؤشر متأخر ولا يكفي وحده لتحديد موضع خلل العملية.", "Training can improve order accuracy, reduce rework and delivery time, and ultimately improve retention and margin. Specify a training, defect, delivery and customer metric with dates, then test the assumed links. Profit is lagging and cannot locate a process defect by itself."],
     ["تجنب تحسين مؤشر بإفساد آخر", "Avoid local metric gaming", "تخفيض زمن المكالمة في خدمة العملاء قد يزيد عدد الحالات غير المحلولة؛ خفّض الزمن مع متابعة نسبة الحل من أول مرة ورضا العميل. لا تجعل بطاقة الأداء مكافأة تلقائية بمقياس لم يُراجع عند تغير الاستراتيجية أو الأهداف. تختلف مؤشرات المصنع عن مكتب الخدمات لكن الزوايا الأربع تبقى إطارًا.", "Shorter support calls may leave more issues unresolved; pair call duration with first-contact resolution and satisfaction. Review targets when strategy changes. Factory and service units use different measures under the same four perspectives."]],
    "اكتب هدفًا استراتيجيًا؛ ارسم علاقته بمقاييس مالية وغير مالية عبر الزوايا الأربع؛ عين مالكًا وتواترًا ومصدرًا؛ راقب المفاضلات وتحقق من العلاقة السببية.",
    "State a strategic objective; map financial and nonfinancial indicators across four perspectives; assign owner, frequency and source; test tradeoffs and causal links.",
    "ليست كل زيادة في مؤشر نشاط تحسن النتيجة النهائية؛ عدد ساعات التدريب دون تحسن جودة ليس برهانًا على فاعليته.",
    "More measured activity is not automatically better performance; training hours without quality change do not establish effectiveness.",
    ["تصنيف مؤشرات", "Classify scorecard metrics", "شركة تقيس هامش التشغيل والاحتفاظ بالعملاء وزمن إصلاح العيوب وساعات تدريب العاملين. صنف كل مقياس في منظور البطاقة.", "A firm measures operating margin, customer retention, defect-repair time and employee training hours. Assign each to a scorecard perspective.", "الهامش مالي، والاحتفاظ منظور العميل، والإصلاح منظور العمليات، والتدريب التعلم والنمو؛ قارنها معًا بدل تعظيم أحدها منفردًا.", "Margin is financial; retention is customer; repair time is internal process; training is learning and growth. Interpret them together."]],
  ["su16-transfer-pricing",
    "يتراوح سعر التحويل المقبول عادةً بين الحد الأدنى للبائع = التكلفة الإضافية + مساهمة بيع خارجي ضائعة، والحد الأقصى للمشتري = سعر الشراء الخارجي الملائم. عند وجود طاقة عاطلة قد تكون الفرصة الضائعة صفرًا؛ عند امتلاء الطاقة ينبغي إضافة المساهمة المفقودة، لا كامل سعر البيع مرة أخرى.",
    "A feasible transfer price lies between the seller's minimum incremental cost plus foregone outside contribution and the buyer's relevant external alternative. With idle capacity opportunity cost may be zero; at full capacity include lost contribution, not the entire outside price as an extra cost.",
    [["قرار الشركة مقابل أداء القسم", "Company choice and segment incentives", "بائع كلفته المتغيرة 12 وسعره الخارجي 25، ولديه طاقة شاغرة؛ مشتري داخلي يستطيع الشراء بـ21. السعر من 12 إلى 21 يسمح للجانبين بالاستفادة، وقرار الشركة يوفر 9 للوحدة إذا لم توجد تكاليف إضافية. عند امتلاء الطاقة وبقاء بيع خارجي بديل، يصبح الحد الأدنى 12+(25−12)=25؛ فلا يكون التحويل عند 21 منطقيًا.", "A seller with variable cost 12, outside price 25 and idle capacity has an internal buyer whose alternative costs 21. A price from 12 to 21 can motivate both, and the firm saves 9 per unit absent other costs. At full capacity with a displaced outside sale, seller minimum becomes 12+(25−12)=25; internal transfer is no longer attractive at a 21 external alternative."],
     ["طرق التسعير وحوافزها", "Pricing policies and incentives", "قد تحدد الشركة السعر وفق السوق أو تكلفة متغيرة أو كاملة أو تفاوض؛ التكاليف الكاملة تحمل نصيبًا من ثابت قد لا يتغير بالقرار. التسعير المزدوج قد يسجل إيراد البائع بسعر السوق ونفقة المشتري بتكلفة متغيرة؛ فرق الدفاتر دعم مركزي يلغى عند التوحيد، لذا لا يجمع ربح القسمين لقياس ربح الشركة.", "Market, variable cost, full cost and negotiated prices create different segment incentives. Full cost includes allocated fixed amounts that may be irrelevant to the incremental decision. Dual pricing can credit seller at market and charge buyer at variable cost; the difference is a corporate subsidy eliminated in consolidation, so segment profits do not simply sum to corporate profit."]],
    "حدد طاقة البائع وسعره الخارجي ومساهمته الضائعة؛ احسب حد البائع وتكلفة بديل المشتري؛ تفاوض ضمن المجال إن وجد؛ افصل قرار المنشأة عن قياس الأقسام.",
    "Determine seller capacity, outside contribution and opportunity cost; set seller minimum and buyer maximum; negotiate if they overlap; distinguish corporate decision from segment reporting.",
    "معادلة حد التحويل تتغير بتغير الطاقة، ولا تعامل التكاليف الثابتة المخصصة على أنها تكلفة إضافية لمجرد إدراجها في سعر تكلفة كاملة.",
    "Transfer minimum depends on capacity; allocated fixed cost is not necessarily incremental.",
    ["مجال التحويل", "Transfer range", "تكلفة البائع المتغيرة 12 وسعر السوق 25، ولديه طاقة شاغرة. تكلفة شراء المشتري من الخارج 21. ما مجال السعر وكم يوفر القرار للمجموعة للوحدة؟", "Seller variable cost is 12 and outside price 25, with idle capacity. Buyer could purchase outside for 21. Find a feasible price range and the corporate saving per unit.", "من 12 إلى 21، بحسب التفاوض؛ وفر الشركة 21−12=9. السعر المحاسبي الداخلي لا يغير الوفر الكلي. عند فقد بيع خارجي يلزم إعادة حساب الفرصة.", "Price range 12 to 21 by negotiation; firm saves 21−12=9. The internal accounting price does not change corporate savings; displaced external sales would change the minimum."]],
  ["su17-governance",
    "الحوكمة تربط مجلس الإدارة ولجنة المراجعة والإدارة والمراجعة الداخلية وأصحاب المصلحة بنظام مساءلة. في سياق الكتاب الأمريكي تُناقش أحكام FCPA وساربينز أوكسلي SOX وأدوار الإدارة والمدقق في التقارير والرقابة؛ تختلف متطلبات التطبيق بحسب نوع الشركة واختصاصها. ينبغي للّجنة المستقلة الإشراف على إعداد التقرير ومخاطر الاحتيال والعلاقة مع المدقق دون تولي عمل الإدارة اليومي.",
    "Governance assigns oversight and accountability among board, audit committee, management, internal audit and stakeholders. The U.S. textbook discusses FCPA and SOX control and reporting provisions and management/auditor roles; applicability depends on issuer and jurisdiction. Independent audit committee oversight covers reporting, fraud risk and auditors without replacing management's daily control operation.",
    [["خطوط مسؤولية واضحة", "Separate oversight from operation", "تضع الإدارة السياسات وتنفذ ضوابط الموافقة والتسوية وتقيّم فعاليتها. تراقب لجنة المراجعة استقلال المدقق والتقارير الجوهرية، وتقدم المراجعة الداخلية تأكيدًا مستقلًا عن التصميم والتشغيل وتبلغ عن مواطن الضعف. لا يُعفي تعهيد معالجة الرواتب الإدارة من مسؤولية بيانات الرواتب التي تدخل القوائم.", "Management designs, operates and evaluates authorization and reconciliation controls. The audit committee oversees auditor independence and significant reporting matters; internal audit offers independent assurance on design and operation and escalates weaknesses. Outsourcing payroll processing does not relieve management of responsibility for payroll data and reporting."],
     ["الامتثال وثقافة النزاهة", "Compliance and integrity culture", "تُعد الدفاتر والسجلات وسياسات التبليغ وتضارب المصالح جزءًا من الحوكمة؛ توقيع مدير واحد على النموذج لا يثبت فاعلية الرقابة. وثق تقييم المخاطر، واختبر عينات الصرف والاعتماد، وتابع التصحيح. تميز بين مسؤولية الإدارة عن الرقابة وبين رأي المدقق الخارجي وفق نطاق التكليف والمتطلبات المطبقة.", "Books and records, whistleblowing routes and conflict-of-interest policies support governance; a signed form alone does not prove effective control. Document risk assessment, test approvals and disbursements, and track remediation. Distinguish management responsibility from the external auditor's opinion under the applicable engagement and reporting rules."]],
    "ارسم الجهات والصلاحيات؛ حدد متطلبات الحالة الأمريكية المذكورة في المصدر ونطاقها؛ اختبر استقلال الرقابة ومسارات الإبلاغ؛ راجع ضعفًا جوهريًا وخطة العلاج.",
    "Map roles and authority; identify which textbook U.S. requirements apply to the scenario; test oversight independence and reporting channels; track deficiencies and remediation.",
    "لا تعتبر وجود سياسة ورقية إثباتًا لتشغيلها، ولا تطبق التزام شركة أمريكية مدرجة على كل منشأة أو بلد بلا تحقق.",
    "A policy document is not operating evidence; issuer-specific U.S. obligations do not automatically apply to every entity or jurisdiction.",
    ["إشراف أم تنفيذ؟", "Oversight or operation?", "اكتشفت لجنة المراجعة أن مدير المالية يوافق على مدفوعات نفسه وأن مدققًا داخليًا لم يفحصها. من يغير الإجراء ومن يراقب العلاج؟", "The audit committee finds that a finance manager approves their own payments and internal audit has not tested them. Who changes the process and who oversees remediation?", "الإدارة تصمم تفويضًا مستقلًا وفصلًا في الدفع والتسوية، والمراجعة الداخلية تختبر التشغيل، واللجنة تتابع نتائج التصحيح واستقلال المراجعة.", "Management implements independent authorization and separation of payment and reconciliation; internal audit tests operation; the committee monitors remediation and audit independence."]],
  ["su17-risk-controls",
    "الرقابة الداخلية عملية تمنح تأكيدًا معقولًا بشأن التشغيل والتقرير والامتثال، وتتكون وفق COSO من بيئة رقابة، وتقييم مخاطر، وأنشطة رقابية، ومعلومات واتصال، ومتابعة. خطر ملازم يرتبط بطبيعة العملية قبل الرقابة، وخطر الرقابة هو فشل منع التحريف أو اكتشافه وتصحيحه في الوقت المناسب؛ المخاطر المتبقية تستدعي استجابة ومراقبة.",
    "Internal control is a process providing reasonable assurance on operations, reporting and compliance. COSO's five components are control environment, risk assessment, control activities, information/communication and monitoring. Inherent risk exists before controls; control risk is failure to prevent or timely detect/correct misstatement. Residual risk still requires response and monitoring.",
    [["من هدف إلى نشاط رقابي", "Map objectives to controls", "إذا كان هدف التقارير إثبات مبيعات موجودة ومصرحًا بها، فخطر فواتير وهمية يستدعي صلاحيات منفصلة وربط الطلب والتسليم والفاتورة واختبار تسويات الذمم. ضع مالكًا لكل إجراء وأثرًا محفوظًا؛ إعادة تحليل المخاطر عند إطلاق قناة بيع جديدة مهمة بقدر اختبار تصميم الرقابة الأصلية.", "If reporting requires valid authorized sales, fictitious invoices call for separate access rights, order-delivery-invoice matching and receivable reconciliation testing. Assign owners and retain evidence. Reassess risks when a new sales channel launches, not only at initial control design."],
     ["حدود التأكيد والاستجابة", "Reasonable assurance and response", "التواطؤ أو تجاوز الإدارة أو تعطل النظام قد يضعف ضابطًا جيد التصميم؛ لا توجد ضمانات مطلقة. قارن احتمال الخطر وأثره مع تكلفة الضابط، ثم اختر التجنب أو التخفيض أو المشاركة أو القبول، واختبر النتائج بمرور الزمن. ضعف جوهري في الرقابة على التقرير لا يشترط وقوع خطأ مادي فعلي حتى يستحق الإبلاغ وفق معيار الحالة.", "Collusion, management override or system failure can defeat a well-designed control; assurance is reasonable, not absolute. Weigh likelihood, impact and control cost, then avoid, mitigate, share or accept risk, and test results over time. A material control weakness can warrant reporting even without an actual material misstatement under the relevant standard."]],
    "حدد الهدف والخطر الملازم؛ حدد الضابط والمكون COSO؛ اختبر التصميم والتشغيل؛ قيّم الخطر المتبقي والتغيير والاحتيال؛ بلغ عن الضعف وتابع العلاج.",
    "Specify objective and inherent risk; map controls to COSO components; test design and operation; reassess residual, change and fraud risks; report deficiencies and follow remediation.",
    "الفحص الخارجي لا يحل محل الرقابة اليومية؛ معادلة مخاطر التدقيق ليست نسبة مضمونة لاختفاء الاحتيال.",
    "External audit does not substitute for daily controls; audit-risk models are not guarantees that fraud is absent.",
    ["تطبيق COSO", "Apply COSO", "لاحظت منشأة أن تسويات البنك تُعد متأخرة، وأن صلاحية تعديل المورد والدفع لشخص واحد. حدد الخطر والضابطين ومكون COSO الرئيس.", "Bank reconciliations are late, while one employee can edit vendors and release payments. Identify the risks, two controls and primary COSO component.", "خطر تحويل دفعة لمورد وهمي وعدم اكتشافها سريعًا؛ فصل تعديل المورد عن اعتماد الدفع، وتسوية بنكية مستقلة وفي موعدها. كلاهما أنشطة رقابة، مع متابعة للتأكد من التشغيل.", "Risk: diversion to fictitious vendors without timely detection. Separate vendor changes from payment release; perform timely independent bank reconciliations. Both are control activities with monitoring of execution."]],
  ["su18-control-procedures",
    "تشمل الرقابة الوقائية التفويض والفصل بين الحيازة والتسجيل والموافقة، والكاشفة تسويات البنك والجرد والاستثناءات، والتصحيحية علاج السبب واستعادة البيانات. يختلف هدف اكتمال المعاملات عن وجودها ودقتها؛ ويجب فصل صلاحيات إنشاء المورد وإقرار الفاتورة وإطلاق الدفع حيثما تسمح الموارد.",
    "Preventive controls include authorization and segregation of custody, recording and approval; detective controls include bank reconciliation, inventory counts and exception reports; corrective controls restore service and fix root causes. Completeness, existence and accuracy are distinct assertions. Separate vendor creation, invoice approval and payment release when practical.",
    [["سلسلة مشتريات قابلة للتتبع", "Trace purchasing end to end", "يربط طلب شراء معتمد بإذن استلام وفاتورة مورد قبل الدفع عبر مطابقة ثلاثية؛ تُرقم المستندات متسلسلًا وتراجع الأرقام الناقصة لكشف معاملات غير مسجلة. يطابق موظف مستقل كشف البنك والأستاذ ويحصر البنود المعلقة ويصعد القديمة. التوثيق مهم لأن توقيعًا شكليًا بلا تحقق لا يمنع فاتورة مكررة.", "Three-way matching ties authorized purchase order, goods receipt and vendor invoice before payment. Numbered documents and sequence-gap review help completeness. An independent employee reconciles bank to ledger and escalates aging items. A checkmark without evidence of comparison will not prevent duplicate invoices."],
     ["ضوابط تعويضية وحدودها", "Compensating controls and limits", "في فريق صغير لا يمكن أحيانًا فصل كل وظيفة، فليوافق مالك مستقل على تغيير بيانات المورد ويراجع تقارير المدفوعات مع كشف البنك أسبوعيًا. هذا يخفف الخطر ولا يزيل احتمال التواطؤ أو تجاوز الصلاحيات؛ سجل من نفذ ومتى ونتيجة المراجعة، ووازن تكلفة الضابط مع الخسارة المتوقعة.", "Small teams may need independent owner approval for vendor master changes and weekly payment-to-bank review when full segregation is impractical. Such controls mitigate but cannot eliminate collusion or override; retain who reviewed what and when, and weigh control cost against expected loss."]],
    "حدد التأكيد والخطر؛ صنف الضابط وقائيًا أو كاشفًا أو تصحيحيًا؛ افصل الوظائف أو أضف ضابطًا تعويضيًا؛ اختبر تنفيذًا فعليًا وأعد معالجة الاستثناءات.",
    "Identify assertion and risk; classify preventive, detective or corrective control; segregate or compensate; test operation and resolve exceptions.",
    "المطابقة الثلاثية لا تثبت وحدها وجود البضاعة إن كان الاستلام مزورًا؛ راقب صلاحيات التعديل وإثبات الاستلام.",
    "Three-way matching alone does not prove physical receipt if receipt records are forged; control access and verify receiving.",
    ["ضابط دفع المورد", "Vendor payment control", "في شركة يستطيع مستخدم واحد تعديل الحساب البنكي للمورد وإصدار التحويل وتسوية البنك. اقترح ضابطًا وقائيًا وكاشفًا.", "One user can change vendor bank details, release transfers and reconcile the bank. Propose a preventive and a detective control.", "اجعل تغيير الحساب واعتماد الدفع لدى شخصين مستقلين مع تحقق خارج القناة؛ وكلف ثالثًا بتسوية البنك وفحص تغييرات الموردين والتقارير الاستثنائية.", "Require separate approval and independent verification of bank-detail changes and payments; a third person reconciles bank statements and reviews vendor-change and exception logs."]],
  ["su18-systems-security",
    "تبدأ الرقابة على النظم بمدخلات صالحة وكاملة، ثم معالجة صحيحة، ومخرجات موجهة لمن يملك حق الاطلاع، وتخزين محمي وقابل للاستعادة. ضوابط عامة مثل إدارة الصلاحيات والتغيير والنسخ تدعم ضوابط التطبيق مثل تحقق الحقول والمجاميع الرقابية؛ يمنح مبدأ أقل صلاحية المستخدم ما يحتاجه فقط.",
    "Information-system controls cover valid complete input, correct processing, authorized output and protected recoverable storage. General controls such as access, change management and backup support application controls such as field validation and control totals. Least privilege limits each user to required actions.",
    [["تتبع دفعة بيانات", "Trace a transaction batch", "أدخل 50 فاتورة بمجموع 80,000؛ يتحقق نظام الإدخال من عدد ومجموع الدفعة وتواريخ وأرقام غير مكررة. تقارن المعالجة إجمالي ما قُبل وما رُفض وما رُحل إلى الأستاذ؛ تراجع المخرجات رقم الدفعة وسجل الأخطاء. فرق 2,000 لا يُحل بإعادة تشغيل عمياء قد تضاعف القيد، بل بعزل الخطأ وتوثيق إعادة المعالجة.", "A batch of 50 invoices totals 80,000. Input checks count, amount, dates and duplicate IDs. Processing reconciles accepted, rejected and posted totals; output reports batch ID and exceptions. A 2,000 difference calls for isolation and logged reprocessing, not blind reruns that could duplicate entries."],
     ["وصول وتغيير ومراقبة", "Access and change controls", "تكون صلاحية المطور لقاعدة الإنتاج محدودة ومراقبة؛ يمر تعديل قاعدة احتساب الضريبة بموافقة واختبار وفصل بيئة قبل النشر. استخدم مصادقة متعددة العوامل وسجل تدقيق لا يستطيع مستخدم عادي محوه وتشفيرًا مناسبًا للبيانات في النقل والتخزين. راجع حسابات موظف مغادر فورًا واختبر استرداد نسخة حقيقية.", "Restrict and log developer access to production. A tax-calculation change requires approval, testing and separation before release. Use multifactor authentication, tamper-resistant audit logs and suitable encryption in transit and at rest. Revoke departing staff promptly and test actual restores."]],
    "اربط تأكيد المعاملة بمدخلات ومعالجة ومخرجات وتخزين؛ اختبر المجاميع والأخطاء؛ راجع الأدوار والتغييرات والسجلات والنسخ؛ تحقق من إعادة المعالجة.",
    "Map assertions across input, processing, output and storage; test control totals and errors; review roles, change logs and backups; verify reprocessing.",
    "وجود نسخة احتياطية أو كلمة مرور لا يثبت إمكانية الاسترجاع أو منع وصول غير مصرح؛ اختبرهما وألغِ صلاحيات المنتهية خدمتهم.",
    "A backup file or password does not prove recoverability or authorization; test restores and revoke stale access.",
    ["مجموع دفعة", "Batch control total", "أُدخلت 50 فاتورة بمجموع 80,000، قبل النظام 49 بمجموع 78,000 ورفض واحدة. ما قيمة المرفوضة، وما الضابط اللاحق؟", "A batch has 50 invoices totaling 80,000; the system accepted 49 totaling 78,000 and rejected one. Find the rejected amount and the next control step.", "قيمة المرفوضة 2,000؛ طابق العدد والمبلغ وسجل سبب الرفض وصححه ثم رحلها مرة واحدة برقم فريد. لا تعد ترحيل كامل الدفعة.", "Rejected amount 2,000; reconcile count and amount, document and correct the exception, then post once under a unique ID. Do not repost the entire batch."]],
  ["su18-continuity",
    "تحمي استمرارية الأعمال وظائف المنشأة الحرجة، بينما تركز خطة التعافي التقني على استرجاع الأنظمة والبيانات. يحدد RTO أقصى مدة مقبولة للانقطاع وRPO أقصى فقد مقبول للبيانات زمنًا؛ موقع بديل جاهز يختلف عن موقع يحتاج تركيبًا، والنسخ غير المختبر لا يضمن الاستعادة. تُصمم الخطة من تحليل أثر توقف العمليات.",
    "Business continuity preserves critical services; disaster recovery restores systems and data. RTO is the target maximum downtime, RPO the tolerable age of recoverable data. A ready alternate site differs from one requiring installation, and untested backup files do not demonstrate recovery. Business impact analysis sets priorities.",
    [["اضبط النسخ وفق RPO", "Design to a recovery point", "إذا احتاجت خدمة دفع ألا تفقد أكثر من ساعة معاملات، فإن نسخة يومية وحدها لا تحقق RPO=ساعة؛ يلزم نسخ متكرر أو سجل معاملات مكرر ومختبر. إذا كان RTO أربع ساعات، اختبر تشغيل الخدمات والموظفين والاتصال مع البنك في أقل من أربع ساعات، لا مجرد تشغيل الخادم.", "If payment operations can lose at most one hour of transactions, daily backups alone fail an RPO of one hour; use more frequent or replicated tested logs. For a four-hour RTO, test application, personnel and bank connectivity in that window, not only server boot time."],
     ["أمن الاسترداد", "Secure the recovery path", "تحفظ النسخ في موقع منفصل بصلاحيات مشددة وتشفير ومراجعة سلامة، لتقاوم الحريق والبرمجيات الخبيثة معًا. وثق مسؤول إعلان الكارثة، وترتيب استعادة النظام والبدائل اليدوية والتواصل والعمل بعد العودة؛ جرب سيناريوهات فقد مورد سحابي أو مركز بيانات وحدّث الخطة بنتائج الاختبار.", "Keep backups separated with restricted access, encryption and integrity review to survive both physical loss and ransomware. Document who declares an incident, restoration order, manual alternatives, communication and return to normal; exercise cloud and data-center outage scenarios and update from test results."]],
    "حلل أثر الانقطاع وحدد الوظائف الحرجة؛ ثبت RTO وRPO؛ اختر وتيرة نسخ وموقعًا بديلًا؛ اختبر استعادة البيانات والعمليات والأشخاص؛ عالج نتائج التجربة.",
    "Conduct business impact analysis, set RTO/RPO, choose backup interval and alternate site, test data and process recovery with people, and remediate gaps.",
    "RTO زمن استعادة وRPO نقطة استرجاع؛ لا تعكسهما أو تفترض أن تكرار النسخ وحده يحقق زمن تشغيل سريعًا.",
    "RTO is downtime and RPO is data-loss window; backup frequency alone does not establish rapid service restoration.",
    ["تحقق من خطة النسخ", "Check backup cadence", "هدف فقد البيانات الأقصى ساعتان لكن النسخ الكامل مرة كل 24 ساعة بلا سجلات إضافية. هل تحقق الخطة RPO؟", "The maximum acceptable data-loss window is two hours, but full backups run every 24 hours with no incremental logs. Does the design meet RPO?", "لا؛ قد تُفقد قرابة 24 ساعة من العمليات. يلزم تكرار أو تسجيل/نسخ متواصل مع اختبار الاسترداد، ثم تحقق مستقل من RTO.", "No; nearly 24 hours could be lost. Use more frequent or continuous logged copies and test restoration; evaluate RTO separately."]],
  ["su19-accounting-systems",
    "نظام AIS جزء من معلومات الإدارة MIS، يضم معالجة معاملات TPS ودفترًا عامًا وتقارير مالية GL/FRS وتقارير إدارة MRS. يربط ERP وحدات المبيعات والمشتريات والمخزون والرواتب لتقليل الإدخال المكرر، ويخدم مستودع البيانات التحليل التاريخي عبر مصادر متعددة بينما يركز data mart على مجال محدد.",
    "AIS sits within MIS and includes transaction processing (TPS), general ledger/financial reporting (GL/FRS), and management reporting (MRS). ERP links sales, purchasing, stock and payroll to reduce duplicate capture. A data warehouse integrates historical data for analysis across sources, whereas a data mart focuses on a subject or department.",
    [["من حدث إلى تقرير", "Follow a transaction to reporting", "يُنشئ بيع آجل حدثًا في TPS برقم فريد، يحدّث الذمم والمخزون وتكلفة المبيعات، ويرحل أثره إلى الأستاذ والقوائم، ثم يظهر في تحليل هامش الإدارة. يجب أن تنجح المعاملة أو تفشل كوحدة؛ ترحيل الإيراد دون الذمم أو المخزون يفسد التوازن. افصل صلاحيات إنشاء العميل واعتماد الحد الائتماني.", "A credit sale enters TPS under a unique ID, updates receivables, stock and COGS, posts to the GL and financial statements, then informs margin reports. The transaction should commit or fail as a unit; posting revenue without its receivable or inventory side corrupts records. Separate customer creation from credit authorization."],
     ["تكامل المخزن دون فقد السلالة", "Integrate data with lineage", "تجمع طبقة ETL أو ELT بيانات نظم مختلفة وتوحد مفاتيح العميل وفترة القيد قبل عرضها في مستودع البيانات. لا تعالج لوحة معلومات قديمة مشكلة المصدر؛ سجل وقت التحديث وقواعد التحويل ووازن المجموع مع الأستاذ. البيانات التشغيلية في ERP للمعاملات، ومخزن التحليل مصمم لاستعلامات الاتجاهات وليس لإصدار الفواتير الأصلية.", "ETL or ELT combines sources and harmonizes customer keys and posting periods before the warehouse serves analysis. A dashboard cannot repair incorrect source data; log refresh time and transformation rules and tie aggregates to the ledger. Operational ERP handles transactions; analytical storage serves trends rather than issuing original invoices."]],
    "حدد نظام مصدر المعاملة والرقم الفريد؛ تتبع أثرها في TPS وGL/FRS وMRS؛ وازن المجاميع عبر ERP والمخزن؛ وثق التحويل والتحديث والصلاحيات.",
    "Identify event source and unique ID; trace it through TPS, GL/FRS and MRS; reconcile ERP and warehouse totals; document transformation, refresh and access.",
    "ERP يوحد التدفق لكنه لا يضمن صحة مدخلات خاطئة؛ مخزن البيانات ليس دفترًا عامًا بديلًا دون حوكمة وتسويات.",
    "ERP integration cannot guarantee correct input; a warehouse is not a substitute ledger without governance and reconciliations.",
    ["تسوية بيانات البيع", "Reconcile a sales load", "في ERP بلغت مبيعات اليوم 1,000 سجل بقيمة 500,000؛ مستودع البيانات يظهر 990 بقيمة 496,000. ما فرق العدد والمبلغ وأول اختبار؟", "ERP has 1,000 sales records worth 500,000 today; the warehouse shows 990 records worth 496,000. Find count and value gaps and the first check.", "الفرق 10 سجلات و4,000؛ طابق المعرفات الفريدة وتاريخ التحميل وسجل رفض التحويل قبل الاعتماد على لوحة الإيرادات.", "The gaps are 10 records and 4,000; compare unique transaction IDs, refresh timestamps and rejected load logs before relying on the revenue dashboard."]],
  ["su19-data-governance",
    "تحدد حوكمة البيانات من يملك التعريف ويوافق على الوصول ويصحح جودة السجل ويقرر حفظه وإتلافه. دورة الحياة تشمل الجمع والتخزين والاستخدام والمشاركة والأرشفة والإزالة؛ وتُقاس الجودة بالدقة والاكتمال والاتساق والتوقيت. سياسات الاحتفاظ تعتمد الالتزامات المطبقة وحاجة العمل، فلا يحدد هذا الدليل مدة قانونية عامة لكل سجل.",
    "Data governance defines ownership, access approval, quality stewardship, retention and disposal. The life cycle covers capture, storage, use, sharing, archiving and deletion; data quality includes accuracy, completeness, consistency and timeliness. Retention periods depend on applicable obligations and business needs rather than one universal number.",
    [["قاموس بيانات وسلالة", "Definitions and lineage", "قد تعني «المبيعات» عند فريق التجارة إجمالي الطلبات قبل المرتجعات، وعند المالية صافي الإيراد المعترف به؛ لا تقارن الرقمين دون تعريف وفترة ومصدر. وثق الحقول والمفاتيح والتحويلات ومالك البيانات والموافقة على التصحيح؛ أضف قياسًا لنسبة العملاء بلا رقم ضريبي أو للفواتير المكررة.", "'Sales' may mean orders before returns in commerce and recognized net revenue in finance. Define period, source and business meaning before comparison. Document fields, keys, transformations, data owner and correction approval; track missing tax IDs or duplicate invoices as quality measures."],
     ["احتفاظ وإزالة قابلة للإثبات", "Retention and deletion evidence", "صنف الرواتب وبيانات العميل والتقارير بحسب الحساسية والغرض والالتزام؛ امنح الوصول حسب الدور واحتفظ بسجل طلبات التصدير. عند انتهاء مدة الاحتفاظ المعتمدة وبعد فحص أي تعليق قانوني، أتلف البيانات بطريقة تمنع استعادتها غير المصرح بها، ووثق التنفيذ في النسخ والخدمات المتعاقد معها بالحد الممكن.", "Classify payroll, customer and report data by sensitivity, purpose and applicable requirement; grant role-based access and log exports. At the approved retention end, after legal-hold checks, dispose securely and document execution across backups and vendors as feasible."]],
    "عين مالكًا وقاموسًا وتعريفات؛ ضع اختبارات جودة وصلاحيات؛ تتبع دورة الحفظ والاستخدام؛ راجع سياسة المدة والتعليق والإتلاف وسجلها.",
    "Assign owner and dictionary, validate quality and access, trace storage/use, and review retention, holds and documented disposal.",
    "لا تساوِ كثرة البيانات بجودتها، أو تحذف نسخة سجل مطلوب الاحتفاظ بها قبل مراجعة السياسة النظامية.",
    "Volume does not mean quality, and records under a valid retention or legal hold must not be purged prematurely.",
    ["تعريف مبيعات موحد", "Unify revenue definitions", "لوحة التجارة تعرض 220,000 طلبات قبل مرتجعات 20,000، والدفتر يسجل صافي 200,000. هل الفرق خطأ ترحيل؟", "Commerce dashboard shows 220,000 gross orders before 20,000 returns, while the ledger has net revenue 200,000. Is the difference necessarily a posting error?", "ليس بالضرورة؛ 220,000−20,000=200,000. تحقق من التعريف والفترة ومعرفات المرتجعات قبل تصحيح البيانات أو اتهام النظام.", "Not necessarily: 220,000−20,000=200,000. Align definition, time period and return IDs before changing source data."]],
  ["su19-coso-data",
    "تُستخدم مكونات COSO الخمسة لفحص البيانات أيضًا: ثقافة ملكية البيانات، وتحديد خطر فقدها أو تحريفها، وضوابط الصلاحيات والجودة، وتبادل معلومات التعريف والأخطاء، ومراقبة مستمرة. تعتمد جودة لوحة الإدارة على عناصر مصدرها وسلالة تحويلها؛ ينشأ الخطر من التغيير غير المصرح أو تحميل ناقص أو تعريفين مختلفين للحقل.",
    "COSO's five components also frame data governance: ownership culture, risk of corruption or loss, access/quality activities, communication of definitions and exceptions, and ongoing monitoring. Dashboard quality depends on source and transformation lineage; risks include unauthorized changes, partial loads and inconsistent field definitions.",
    [["خريطة خطر وضابط ومؤشر", "Risk-control-metric map", "إذا أمكن لمحلل تعديل جدول العملاء الأصلي وتقرير الإيراد دون مراجعة، فخطر التقارير غير الصحيحة يرتفع. قيد الكتابة على المصدر، وافصل التعديل عن الاعتماد، واحفظ سجل نسخة التحويل، ووازن إجمالي الفواتير بين المصدر والمخزن يوميًا. راقب نسبة سجلات مرفوضة ومدة علاجها وصعّد الاختلافات.", "If an analyst can change master customers and revenue output without review, reporting risk rises. Restrict source writes, separate change from approval, version transformations and reconcile source-to-warehouse invoice totals daily. Monitor rejected-record rate and resolution time and escalate discrepancies."],
     ["البيئة والمراقبة لا تقلان عن الكود", "Culture and monitoring matter", "وثق مسؤول إدارة البيانات وتوقعات النزاهة والتدريب، ثم قيّم الأخطاء المتكررة وتغييرات مصادر البيانات. فحص آلي واحد عند بدء المشروع لا يكفي عندما يتغير ERP أو قواعد احتساب الإيراد؛ اختبر دوريًا فعالية الضوابط وإبلاغ الاستثناءات. التأكيد معقول وليس مطلقًا بسبب أخطاء البشر والتجاوز والتواطؤ.", "Define data stewardship, integrity expectations and training, then assess recurring exceptions and source changes. A one-time automated check is insufficient after ERP or revenue-rule changes; test operation and exception communication regularly. Assurance is reasonable rather than absolute because of error, override and collusion."]],
    "حدد هدف جودة التقرير ومخاطر البيانات؛ اربط الضابط بمكون COSO؛ وثق المصدر والتحويل والصلاحيات؛ وازن النتائج وراقب الاستثناءات والإصلاح.",
    "Define reporting quality objective and data risk; map each control to COSO; document lineage and rights; reconcile results, monitor exceptions and remediation.",
    "وجود لوحة بيانات لا يعني موثوقية مدخلاتها؛ لا تصنف مراجعة لاحقة بديلًا عن منع تعديل غير مصرح به.",
    "A dashboard does not validate its own inputs; detective review is not a substitute for preventing unauthorized edits.",
    ["اكتمال تحميل البيانات", "Data-load completeness", "أرسل TPS مبلغ 800,000 إلى المخزن، لكن التقرير يعرض 792,000 بسبب 8 سجلات مرفوضة بقيمة 8,000. ما الضابط والمكون؟", "TPS sends 800,000 to the warehouse, but reporting shows 792,000 because eight records totaling 8,000 were rejected. Identify a control and COSO component.", "تسوية المجاميع اليومية وسجل استثناءات لإعادة معالجة السجلات مرة واحدة، ثم تصعيد فروق لم تُحل؛ ذلك من أنشطة الرقابة، وتغذيه المعلومات والاتصال والمتابعة.", "Daily control-total reconciliation and an exception log for one-time reprocessing, with escalation of unresolved gaps; primarily control activities, supported by information/communication and monitoring."]],
  ["su20-finance-transformation",
    "يبدأ تطوير النظام بتحديد الحاجة والجدوى ثم المتطلبات والتصميم والبناء والاختبار والنشر والدعم؛ يجب إشراك المالية في القبول وربط السجلات بالقوائم. تؤتمت RPA القواعد المتكررة، وتستخدم أدوات الذكاء الاصطناعي في التنبؤ أو التصنيف مع حاجة لمراجعة بيانات التدريب والنتائج. يتيح السحاب المرونة لكنه يضيف مسؤولية مشتركة في الهوية والنسخ والمورد.",
    "System development starts with need and feasibility, then requirements, design, build, test, deployment and support; finance should sign off on reconciliation and acceptance. RPA automates rule-based repetitive work; AI prediction or classification needs training-data and outcome review. Cloud offers flexibility with shared responsibility for identity, backup and vendor oversight.",
    [["التحليل قبل الأتمتة", "Specify before automating", "قبل روبوت ترحيل فاتورة، حدد مصدر الفاتورة وتحقق المبلغ والضريبة والمورد والتكرار والحد الائتماني؛ وثق كيف تعالج الاستثناءات وكيف تمنع إعادة التشغيل قيدًا ثانيًا. بعد ذلك اختبر قبول المستخدم على حالات سليمة وخاطئة وحالات توقف الخدمة، ثم قارن مجموع الفواتير المرحل بالأصل.", "Before an invoice-posting bot, define input source and amount, tax, vendor, duplicate and authorization checks; document exception handling and how reruns avoid double posting. Test valid, invalid and outage scenarios at user acceptance, then tie posted invoice totals to the source."],
     ["اختيار منصة ومخاطرها", "Platform and change risk", "حل جاهز قد يختصر البناء لوظيفة شائعة، بينما تتطلب حاجة فريدة تطويرًا مخصصًا؛ قيّم التكلفة الكلية والقابلية للتكامل وأمن البيانات والخروج من المورد. في السحاب لا تنقل مسؤولية حماية الحسابات والتصنيف للمورد؛ احفظ موافقات التغيير وخطة رجوع، وراقب انجراف نموذج AI والتحيز والدقة بعد النشر.", "A commercial package can shorten common-function delivery; unusual needs may require in-house code. Compare life-cycle cost, integration, security and vendor exit. Cloud outsourcing does not transfer responsibility for identity and data classification; keep change approvals, rollback and post-release AI drift, bias and accuracy monitoring."]],
    "حدد حاجة العملية ومؤشرات النجاح؛ أجرِ الجدوى والمتطلبات؛ صمم واختبر القبول والضوابط؛ انشر بخطة رجوع؛ راقب الاستثناءات والجودة وتكلفة الصيانة.",
    "Define need and success metrics, assess feasibility and requirements, design and test controls, deploy with rollback, then monitor exceptions, quality and maintenance cost.",
    "أتمتة خطأ موجود تزيد سرعة تكراره؛ لا تجعل مخرجات AI التي تؤثر في القيد المحاسبي تمر بلا مراجعة مناسبة.",
    "Automation can accelerate an existing error; accounting-impacting AI outputs need appropriate review.",
    ["حساب أثر RPA", "RPA savings", "عملية 4,000 فاتورة سنويًا تستغرق 3 دقائق يدويًا، وبعد روبوت دقيقة مراجعة لكل فاتورة. تكلفة الساعة 30، وتكلفة الروبوت السنوية 2,000. احسب الوفر الصافي.", "An annual 4,000 invoices take 3 minutes each manually and one minute of review after automation. Labor costs 30/hour and the bot costs 2,000/year. Find net annual saving.", "ساعات موفرة 4,000×(3−1)÷60=133.33؛ وفر عمل 4,000؛ الصافي 2,000 سنويًا قبل تكلفة تطوير أولية ومخاطر الأخطاء.", "Saved hours =4,000×2/60=133.33; labor saving 4,000; net annual benefit 2,000 before initial development and error-risk effects."]],
  ["su20-data-analytics",
    "تميّز البيانات الضخمة بالحجم والسرعة والتنوع والصدق/الموثوقية، ويستخدم التحليل الوصفي لفهم ما حدث، والتنبؤي لتقدير ما قد يحدث، والتوجيهي لاختيار فعل تحت قيود. تُختار الرسوم وفق سؤال القرار: خط للزمن، مبعثر لعلاقة متغيرين، مخطط ضبط لتغير العملية، وباريتو لترتيب أسباب العيوب.",
    "Big data is characterized by volume, velocity, variety and veracity. Descriptive analytics asks what happened, predictive estimates future outcomes, and prescriptive recommends actions under constraints. Choose visuals for the decision: line over time, scatter for association, control chart for process stability and Pareto to rank defect causes.",
    [["من بيانات إلى قرار قابل للاختبار", "Turn data into a testable decision", "إذا أردت توقع التأخر في السداد، اجمع سلوك العملاء والفواتير مع مراعاة فترات البيانات والقيم المفقودة، وقس دقة نموذج تنبؤي على بيانات لاحقة لم تُستخدم في التدريب. التنبؤ بدرجة خطر لا يحدد تلقائيًا سياسة الائتمان؛ الحل التوجيهي يوازن احتمال الخسارة والمبيعات وقيد التمويل، ثم يتحقق من أثره بعد التطبيق.", "To predict late payment, join customer and invoice histories with consistent dates and missing-data rules, then test predictive performance on later untouched data. A risk score does not itself set credit policy; a prescriptive model weighs loss, sales and capital constraints, then checks realized outcomes."],
     ["اختر الرسم وتحقق من عدم تضليله", "Choose an honest chart", "في تحليل عيوب 40 من السبب A و30 من B و20 من C و10 من D، يوضح باريتو أن أول سببين يساويان 70%؛ ابدأ بهما مع فحص تكلفة العلاج. مخطط الضبط يميّز ضجيج العملية عن تغير خاص إذا حددت حدودًا مناسبة. محور يبدأ من 95 بدل صفر قد يضخم فرق أعمدة 98 و100؛ اذكر المقياس والوحدة والمصدر.", "For defects A=40, B=30, C=20 and D=10, Pareto shows the top two make 70%; prioritize them subject to remedy cost. A control chart can distinguish common from special variation with suitable limits. A bar axis starting at 95 exaggerates the difference between 98 and 100; show scales, units and source."],
     ["فسّر العلاقة بحدودها", "Interpret fit with limits", "إذا كان الارتباط بين وقت التدريب والأخطاء r=−0.6، فإن r²=0.36 في انحدار خطي بسيط مع ثابت، أي 36% من تباين الأخطاء في العينة يفسره الخط؛ لا يثبت أن التدريب سبب الانخفاض أو أن احتمالية صحة توقع محدد 36%. راقب المتغيرات المحذوفة ومجال البيانات والانحياز.", "If training time and errors have r=−0.6, then r²=0.36 in a simple regression with intercept: 36% of sample error variation is explained by the line. This is not proof that training caused the decline nor a 36% forecast-success probability. Check omitted factors, range and bias."],
     ["بنية البيانات الضخمة ومخاطرها", "Big-data pipeline and its constraints", "تزداد صعوبة التحليل مع حجم السجلات وسرعة وصولها وتنوع النص والصورة والمعاملات، لكن ضعف صدق المصدر يفسد كل نموذج. عند دمج دفعات نقاط البيع مع سجل العملاء، استعمل مفاتيح فريدة، وتواريخ موحدة، وسياسة للقيم المفقودة، ومراقبة تأخير التحميل؛ وازن أعداد ومبالغ المصدر والمخزن بعد التحويل. الحوسبة السحابية توسع المعالجة لكن تصنيف البيانات والصلاحيات ومدة الحفظ تبقى جزءًا من التصميم.", "Large volume, incoming velocity and mixed text, images and transactions strain processing, while low veracity can invalidate every model. When joining POS batches to customer records, use unique keys, consistent dates, missing-value rules and refresh-lag checks; reconcile source counts and amounts after transformation. Cloud scale does not remove the need for classification, access or retention design."],
     ["ذكاء الأعمال والتنقيب", "Business intelligence and data mining", "تجمع منصة ذكاء الأعمال بيانات موحدة في مستودع أو سوق موضوعي وتعرض مؤشرات بمرشحات زمنية قابلة للتتبع إلى المعاملة. ينقب التحليل عن أنماط مثل التجزئة وتصنيف خطر الائتمان أو ارتباط المشتريات؛ اختبر النمط على بيانات غير مستخدمة في بنائه، وافحص أثر التسرب والتحيز وعدم توازن الفئات. لا يساوي ظهور نمط مرتفع الارتباط توصية تلقائية؛ قارن التكلفة وخطر القرار وصلاحية استعمال البيانات.", "Business intelligence uses governed warehouse or subject-mart data to report metrics with time filters that can be traced to transactions. Data mining finds patterns such as customer segments, credit-risk classes or purchase associations. Validate on held-out periods, detect leakage, bias and class imbalance. A strong pattern does not automatically make a sound recommendation; compare decision cost, risk and permitted data use."],
     ["مكتبة اختيار المرئيات", "Select the visualization by question", "استخدم مخططًا خطيًا لاتجاه الإيراد، وعموديًا لمقارنة أقسام قليلة، ومبعثرًا للارتباط بين متغيرين، ومدرجًا لتوزيع متغير مستمر، وباريتو لترتيب عيوب فئوية مع النسبة التراكمية. مخطط الضبط يتطلب خط وسط وحدود ضبط محسوبة من تذبذب العملية؛ لا تخلطها بأهداف المواصفة. وثق العينة والمقامات، وتجنب ثلاثيات الأبعاد أو محور مقطوع يشوه النسبة.", "Use a line for revenue over time, bars for a few categories, scatter for two-variable association, a histogram for a continuous distribution, and Pareto for ranked categories and cumulative share. A control chart needs a center line and control limits from process variation; these are distinct from specification targets. Label samples and denominators, and avoid 3D or truncated axes that distort comparisons."]],
    "عرّف قرارًا ومقياسًا؛ نظف البيانات ووثق المصدر؛ اختر وصفًا أو تنبؤًا أو توجيهًا؛ تحقق من النموذج والمرئية؛ راقب أثر القرار وانحراف البيانات.",
    "Define decision and metric, clean and trace data, choose descriptive/predictive/prescriptive approach, validate model and visual, and monitor outcomes and drift.",
    "الارتباط لا يثبت السبب؛ العينة التاريخية قد تنحاز؛ لا تستخدم مقياس رسم مقطوعًا لإيهام القارئ بفارق كبير.",
    "Correlation does not prove causation; historical data can be biased; truncated visual scales may overstate effects.",
    ["الأسباب الأكثر تكرارًا", "Defect Pareto", "أسباب عيوب A=40 وB=30 وC=20 وD=10. ما نسبة أول سببين، وأي رسم يرتب العلاج؟", "Defect causes have counts A=40, B=30, C=20, D=10. What fraction comes from the top two, and which chart ranks remediation?", "الإجمالي100؛ أول سببين70%=70÷100، ومخطط باريتو يرتب التكرار تنازليًا مع نسبة تراكمية. الكلفة والأثر يبقيان مهمين لترتيب التدخل.", "Total 100; top two are 70%, and a Pareto chart ranks frequencies and cumulative share. Remedy cost and severity still matter."]],
];

export const CMA_TOPIC_GUIDES_15_20: Record<string, CmaTopicGuide> = Object.fromEntries(
  drafts.map(([id, conceptsAr, conceptsEn, lessons, workflowAr, workflowEn, pitfallsAr, pitfallsEn, example]) => {
    const topic = CMA_TOPICS.find((item) => item.id === id);
    if (!topic || !topic.guidePages) throw new Error(`Missing supplied outline topic/page: ${id}`);
    return [id, {
      topicId: id,
      scope: { ar: `الوحدة ${topic.studyUnit}، القسم ${topic.section}، صفحات دليل 2024: ${topic.guidePages}. ${topic.titleAr}.`, en: `Study Unit ${topic.studyUnit} §${topic.section}, 2024 outline pp. ${topic.guidePages}: ${topic.titleEn}.` },
      concepts: { ar: conceptsAr, en: conceptsEn },
      lessonSections: lessons.map(([ar, en, bodyAr, bodyEn]) => ({ heading: { ar, en }, body: { ar: bodyAr, en: bodyEn } })),
      workflow: { ar: workflowAr, en: workflowEn }, pitfalls: { ar: pitfallsAr, en: pitfallsEn },
      practicalCase: { titleAr: example[0], titleEn: example[1], scenarioAr: example[2], scenarioEn: example[3], solutionAr: example[4], solutionEn: example[5] },
    } satisfies CmaTopicGuide];
  }),
);

